<template>
    <div class="code-editor">
        <textarea
            style="display: none"
            readonly
            v-model="code"
            :name="name"
            :data-question="dataQuestion"
            class="accqstXmlInput noRTEditor"
        ></textarea>
        <div
            :class="mainClass"
            :name="name"
            :data-question="dataQuestion"
            ref="editorElement"
        ></div>
    </div>
</template>

<script setup lang="ts">
import ErrorTip from '@/components/ErrorTip.vue'
import { cpp } from '@codemirror/lang-cpp'
import { css } from '@codemirror/lang-css'
import { html } from '@codemirror/lang-html'
import { java } from '@codemirror/lang-java'
import { javascript } from '@codemirror/lang-javascript'
import { json } from '@codemirror/lang-json'
import { python } from '@codemirror/lang-python'
import {
    EditorView,
    highlightSpecialChars,
    drawSelection,
    dropCursor,
    highlightActiveLine,
    keymap,
    lineNumbers,
    ViewUpdate,
    Decoration,
    DecorationSet,
    gutter,
    GutterMarker,
    hoverTooltip,
} from '@codemirror/view'
import {
    indentWithTab,
    defaultKeymap,
    history,
    historyKeymap,
    insertNewlineAndIndent,
} from '@codemirror/commands'
import {
    syntaxHighlighting,
    defaultHighlightStyle,
    indentOnInput,
    bracketMatching,
    foldGutter,
    foldKeymap,
    IndentContext,
    indentService,
    indentUnit,
    getIndentation,
    syntaxTree,
    ensureSyntaxTree,
} from '@codemirror/language'
import { searchKeymap, highlightSelectionMatches } from '@codemirror/search'
import {
    autocompletion,
    completionKeymap,
    closeBrackets,
    closeBracketsKeymap,
    CompletionContext,
    CompletionResult,
} from '@codemirror/autocomplete'
import { lintKeymap } from '@codemirror/lint'
import {
    ChangeSpec,
    Compartment,
    EditorSelection,
    EditorState,
    type Extension,
    type Line,
    RangeSetBuilder,
    StateEffect,
    StateField,
    type Transaction,
    Prec,
} from '@codemirror/state'
import {
    computed,
    ComputedRef,
    createApp,
    nextTick,
    onBeforeUnmount,
    onMounted,
    Ref,
    ref,
    shallowRef,
    toRefs,
    watch,
} from 'vue'

import { useResizeObserver } from '@vueuse/core'
import { IRandomizerSet } from '@/lib/ICodeBlocks'
import { ErrorSeverity, ICompilerErrorDescription } from '@/lib/ICompilerRegistry'
import {
    createTagCompletions,
    createTagMarkField,
    createTagTooltip,
    markTags,
} from '@/plugins/tagHighlighter'
import { basicDarkTheme } from 'cm6-theme-basic-dark'
import { basicLightTheme } from 'cm6-theme-basic-light'
import { solarizedDarkTheme } from 'cm6-theme-solarized-dark'
import { solarizedLightTheme } from 'cm6-theme-solarized-light'
import { getSimpleIndentation } from '@/plugins/codemirror/codeIndentation'
import { CodeSplitSegment } from '@/composables/useCodeEditor'
import {
    createJavaCompletions,
    createJavaScriptCompletions,
    createJsonCompletions,
    createPythonCompletions,
} from '@/plugins/completions'
import { createHighlightStyle } from '@/plugins/codemirror/highlightStyles'
import { getUITheme, UITheme, UIThemeType } from '@/lib/uiTheme'
import { DEFAULT_EDITOR_THEME, EditorTheme, EditorThemes } from '@/plugins/codemirror/editorThemes'
import { createDOMEventHandlers } from '@/plugins/codemirror/keyHandling'
import { createErrorHoverTooltip, ErrorRange } from '@/plugins/codemirror/errorHoverTooltip'

// Add proper typing for the props
interface Props {
    modelValue?: string // Add this to properly type v-model
    name: string
    dataQuestion?: string | number
    theme?: EditorTheme
    language?: string
    firstLine?: number
    readOnly?: boolean
    errors?: ICompilerErrorDescription[]
    maxLines?: number
    tagSet?: IRandomizerSet | undefined
    codeSplitSegment?: CodeSplitSegment
    isEditMode?: boolean
    enableCompletionInViewMode?: boolean
}

// Fix emit types to match expected usage
const emit = defineEmits<{
    'update:modelValue': [string]
    focus: [boolean]
    update: [ViewUpdate]
    change: [EditorState]
    ready: [{ view: EditorView; state: EditorState; container: HTMLElement }]
}>()

const props = withDefaults(defineProps<Props>(), {
    dataQuestion: '',
    theme: () => DEFAULT_EDITOR_THEME,
    language: 'text/javascript',
    firstLine: 1,
    readOnly: false,
    errors: () => [],
    maxLines: 1,
    tagSet: undefined,
    codeSplitSegment: undefined,
    isEditMode: false,
    enableCompletionInViewMode: true,
})
const {
    name,
    dataQuestion,
    theme,
    language,
    firstLine,
    readOnly,
    errors,
    maxLines,
    tagSet,
    codeSplitSegment,
    isEditMode,
    enableCompletionInViewMode,
} = toRefs(props)

// Replace code.value with proper v-model handling
const code = defineModel<string>('modelValue')
const editorElement = ref<HTMLElement | null>(null)
const editorView = shallowRef<EditorView | null>(new EditorView())

const mainClass = computed(() => {
    return {
        ...editorTheme.value.cssClasses,
        accqstXmlInput: true,
        noRTEditor: true,
        over10: maxLines.value >= 10,
        over100: maxLines.value >= 100,
        over1000: maxLines.value >= 1000,
        over10000: maxLines.value >= 10000,
    }
})

const editorTheme = computed<EditorTheme>(() => {
    return theme.value
})

const normalizedLanguage = computed(() => {
    return (language.value || '').trim().toLowerCase()
})

const isJavaLanguage = computed(() => {
    return ['text/x-java', 'text/java', 'java'].includes(normalizedLanguage.value)
})

const isJavaScriptLanguage = computed(() => {
    return ['text/javascript', 'application/javascript', 'javascript', 'text/js', 'js'].includes(
        normalizedLanguage.value
    )
})

const isJsonLanguage = computed(() => {
    return ['application/json', 'text/json', 'json'].includes(normalizedLanguage.value)
})

const isPythonLanguage = computed(() => {
    return ['text/python', 'text/x-python', 'application/x-python-code', 'python'].includes(
        normalizedLanguage.value
    )
})

const editorLanguage = computed(() => {
    switch (normalizedLanguage.value) {
        case 'text/css':
        case 'css':
            return css()
        case 'text/html':
        case 'html':
            return html()
        case 'text/json':
        case 'application/json':
        case 'json':
            return json()
        case 'text/python':
        case 'text/x-python':
        case 'python':
            return python()
        case 'text/x-java':
        case 'text/java':
        case 'java':
            return java()
        case 'text/cpp':
        case 'text/x-c++src':
        case 'cpp':
        case 'c++':
            return cpp()
        default:
            return javascript()
    }
})

const languageCompartment = new Compartment()
const languageAutoCompleteCompartment = new Compartment()
const themeCompartment = new Compartment()
const highlighterCompartment = new Compartment()
const readOnlyCompartment = new Compartment()
const lineNumbersCompartment = new Compartment()
const indentationCompartment = new Compartment()
const handlersCompartment = new Compartment()

const tagMarkField = createTagMarkField(tagSet)
const tagTooltip = createTagTooltip(tagMarkField, tagSet)

const createIndentService = (): Extension => {
    return indentationCompartment.of(
        indentService.of((context, pos) => {
            return getIndentationInSource(context.state.doc.toString(), pos, indentOptions(context))
        })
    )
}

type IndentOptions = { simulateBreak?: number; simulateDoubleBreak?: boolean }

// `options` is not part of the public typings, but it is what carries the simulated break
const indentOptions = (context: IndentContext): IndentOptions =>
    (context as unknown as { options: IndentOptions }).options

const getIndentationInSource = (
    docString: string,
    pos: number,
    options: IndentOptions = {}
): number => {
    const newState = EditorState.create({
        doc: codeSplitSegment.value
            ? codeSplitSegment.value.before +
              docString +
              (codeSplitSegment.value.after ? '\n' + codeSplitSegment.value.after : '')
            : docString,
        extensions: [EditorState.tabSize.of(4), indentUnit.of('    '), editorLanguage.value],
    })

    const mapPos = (p: number) =>
        codeSplitSegment.value
            ? Math.min(p + codeSplitSegment.value.offset, newState.doc.length)
            : p
    const newPos = mapPos(pos)

    // Force synchronous parse up to newPos to ensure indentation logic has a syntax tree
    ensureSyntaxTree(newState, newPos, 2000)

    // Keep the simulated line break (e.g. from insertNewlineAndIndent), otherwise the
    // indentation is computed as if the cursor were still on the line of the opening bracket
    const simulateBreak =
        options.simulateBreak !== undefined ? mapPos(options.simulateBreak) : undefined
    const context = new IndentContext(newState, {
        simulateBreak,
        simulateDoubleBreak: options.simulateDoubleBreak,
    })
    const indent = getIndentation(context, newPos)

    if (indent !== null) {
        return indent
    }

    // Fallback to simpler indentation logic
    return (
        getSimpleIndentation(
            new IndentContext(newState, { simulateBreak: newPos }),
            newPos,
            () => 0
        ) ?? 0
    )
}

function combinedCompletions(tagSet: Ref<IRandomizerSet | undefined>) {
    const tagCompletions = createTagCompletions(tagSet)

    return (context: CompletionContext): CompletionResult | null => {
        if (!isEditMode.value && !enableCompletionInViewMode.value) {
            return null
        }

        let res: CompletionResult | null = null
        if (tagCompletions && !isJsonLanguage.value) {
            res = tagCompletions(context)
        }
        if (res === null) {
            if (isJavaLanguage.value) {
                return createJavaCompletions(context, { includeRuntime: isEditMode.value })
            }
            if (isJavaScriptLanguage.value) {
                return createJavaScriptCompletions(context, { includeRuntime: isEditMode.value })
            }
            if (isJsonLanguage.value) {
                return createJsonCompletions(context)
            }
            if (isPythonLanguage.value) {
                return createPythonCompletions(context)
            }
        }
        return res
    }
}

const extensions: ComputedRef<Extension[]> = computed(() => {
    return [
        Prec.highest(
            keymap.of([
                {
                    key: 'Enter',
                    run: (view) => {
                        const pos = view.state.selection.main.from
                        const line = view.state.doc.lineAt(pos)
                        const m = line.text.match(/^\s*/)
                        const wsLen = m ? m[0].length : 0
                        const isAtStartOfText = pos <= line.from + wsLen

                        if (isAtStartOfText) {
                            // Indent the new empty line and the (moved down) text line
                            // based on the document as it looks after the break
                            const docString = view.state.doc.toString()
                            const brokenDoc =
                                docString.slice(0, line.from) +
                                '\n' +
                                docString.slice(line.from + wsLen)
                            const upperIndent = getIndentationInSource(brokenDoc, line.from)
                            const lowerIndent = getIndentationInSource(brokenDoc, line.from + 1)
                            view.dispatch({
                                changes: {
                                    from: line.from,
                                    to: line.from + wsLen,
                                    insert:
                                        ' '.repeat(upperIndent) + '\n' + ' '.repeat(lowerIndent),
                                },
                                selection: { anchor: line.from + upperIndent + 1 + lowerIndent },
                                scrollIntoView: true,
                            })
                            return true
                        }
                        return false
                    },
                },
            ])
        ),
        highlightSpecialChars(),
        history(),
        drawSelection(),
        dropCursor(),
        EditorState.allowMultipleSelections.of(true),
        indentOnInput(),
        syntaxHighlighting(defaultHighlightStyle, { fallback: true }),
        bracketMatching(),
        closeBrackets(),
        autocompletion({
            activateOnTyping: true,
        }),
        //highlightActiveLine(),
        highlightSelectionMatches(),
        keymap.of([
            ...closeBracketsKeymap,
            ...defaultKeymap,
            ...searchKeymap,
            ...historyKeymap,
            ...foldKeymap,
            ...completionKeymap,
            ...lintKeymap,
            indentWithTab,
        ]),
        // Combined update listener for focus, updates and tags
        EditorView.updateListener.of((update: ViewUpdate): void => {
            // Handle focus and update events
            emit('focus', editorView.value?.hasFocus ?? false)
            if (!update.changes.empty && update.docChanged) {
                emit('update', update)
                // Handle tag updates when document changes
                markTags(update.view, tagSet)
            }
        }),
        readOnlyCompartment.of(EditorState.readOnly.of(readOnly.value)),
        EditorView.editable.of(true),
        EditorState.tabSize.of(4),
        indentUnit.of('    '),
        themeCompartment.of(editorTheme.value.editorTheme),
        languageCompartment.of(editorLanguage.value),
        lineNumbersCompartment.of(
            lineNumbers({
                formatNumber: (n, state) => lineNr(n),
            })
        ),
        handlersCompartment.of(createDOMEventHandlers(getIndentationInSource)),
        highlighterCompartment.of(editorTheme.value.highlightStyle),
        languageAutoCompleteCompartment.of(
            editorLanguage.value.language.data.of({
                autocomplete: combinedCompletions(tagSet),
            })
        ),
        tagMarkField,
        tagTooltip,
        underlineField,
        createErrorHoverTooltip(errorRanges),
        errorGutter,
        createIndentService(),
    ] as Extension[]
})

// WebKit (Safari) does not re-layout the scroller's flex box when its horizontal
// scrollbar (dis)appears, e.g. because the editor width changed while the page was
// still being laid out. The editor then keeps its old height: an empty strip below the
// last line when the scrollbar is gone, or a scrollbar covering the last line when it
// was added. Any style change on the scroller forces a re-layout. As the layout can
// settle at any time, we check whenever the editor resizes instead of once after a
// fixed delay.
const fixStaleScrollerHeight = () => {
    const view = editorView.value
    if (!view) {
        return
    }

    const scroller = view.scrollDOM
    const scrollbarHeight = scroller.offsetHeight - scroller.clientHeight
    const expectedHeight = view.contentDOM.offsetHeight + scrollbarHeight
    if (Math.abs(scroller.offsetHeight - expectedHeight) <= 1) {
        return
    }

    scroller.style.flexShrink = '0'
    void scroller.offsetHeight // force a synchronous re-layout
    scroller.style.flexShrink = ''
    view.requestMeasure()
}

useResizeObserver(editorElement, () => requestAnimationFrame(fixStaleScrollerHeight))

onMounted(() => {
    if (editorElement.value === null) {
        console.error('Editor Element is not found.')
        return
    }

    editorView.value?.destroy()
    editorView.value = new EditorView({
        parent: editorElement.value,
        state: EditorState.create({ doc: code.value, extensions: extensions.value }),
        dispatch: (tr: Transaction) => {
            if (editorView.value === null) {
                return
            }
            editorView.value.update([tr])
            if (tr.changes.empty || !tr.docChanged) {
                // if not change value, no fire emit event
                return
            }

            code.value = tr.state.doc.toString() ?? ''
            emit('change', tr.state)
        },
    })

    nextTick(() => {
        if (editorView.value === null || editorElement.value === null) {
            return
        }

        // Initialize error underlining
        underlineErrors()

        // Initialize tag marks
        markTags(editorView.value, tagSet)

        emit('ready', {
            view: editorView.value,
            state: editorView.value.state,
            container: editorElement.value,
        })
        fixStaleScrollerHeight()
        document.fonts?.ready.then(fixStaleScrollerHeight)
    })
})

onBeforeUnmount(() => {
    editorView.value?.destroy()
})

function lineNr(a: number): string {
    return `${+a + firstLine.value - 1}`
}

watch([codeSplitSegment], () => {
    if (editorView.value) {
        editorView.value.dispatch({
            effects: [
                indentationCompartment.reconfigure(
                    indentService.of((context, pos) => {
                        if (codeSplitSegment.value) {
                            return getIndentationInSource(
                                context.state.doc.toString(),
                                pos,
                                indentOptions(context)
                            )
                        }
                        return getSimpleIndentation(context, pos, () => 0) ?? 0
                    })
                ),
            ],
        })
    }
})

watch(firstLine, (newValue) => {
    if (editorView.value === null) {
        return
    }
    console.log('firstLine', newValue)
    editorView.value.dispatch({
        effects: lineNumbersCompartment.reconfigure(
            lineNumbers({
                formatNumber: (n, state) => lineNr(n),
            })
        ),
    })
})

watch(editorLanguage, (newValue) => {
    if (editorView.value === null) {
        return
    }

    editorView.value.dispatch({
        effects: languageCompartment.reconfigure(newValue),
    })
    editorView.value.dispatch({
        effects: languageAutoCompleteCompartment.reconfigure(
            newValue.language.data.of({
                autocomplete: combinedCompletions(tagSet),
            })
        ),
    })
})

watch(isEditMode, () => {
    if (editorView.value === null) {
        return
    }

    editorView.value.dispatch({
        effects: languageAutoCompleteCompartment.reconfigure(
            editorLanguage.value.language.data.of({
                autocomplete: combinedCompletions(tagSet),
            })
        ),
    })
})

watch(enableCompletionInViewMode, () => {
    if (editorView.value === null) {
        return
    }

    editorView.value.dispatch({
        effects: languageAutoCompleteCompartment.reconfigure(
            editorLanguage.value.language.data.of({
                autocomplete: combinedCompletions(tagSet),
            })
        ),
    })
})

watch(editorTheme, (newValue) => {
    if (editorView.value === null) {
        return
    }

    editorView.value.dispatch({
        effects: [
            themeCompartment.reconfigure(newValue.editorTheme),
            highlighterCompartment.reconfigure(newValue.highlightStyle),
        ],
    })
})

watch(
    () => readOnly.value,
    (value) => {
        if (editorView.value === null) {
            return
        }

        //make the view readonly
        editorView.value.dispatch({
            effects: readOnlyCompartment.reconfigure(EditorState.readOnly.of(readOnly.value)),
        })
    },
    { immediate: true }
)

const SAVE_SELECTION = { anchor: 0, head: 0 }
watch(
    () => code.value,
    async (value) => {
        if (value === undefined) {
            value = ''
        }
        if (
            editorView.value === null ||
            editorView.value.composing ||
            editorView.value.state.doc.toJSON().join('\n') === value
        ) {
            return
        }

        const isOffRange = !editorView.value.state.selection.ranges.every(
            (range) => range.anchor < value.length && range.head < value.length
        )

        editorView.value.dispatch({
            changes: { from: 0, to: editorView.value.state.doc.length, insert: value },
            selection: isOffRange ? SAVE_SELECTION : editorView.value.state.selection,
            scrollIntoView: true,
        })
    },
    { immediate: true }
)

const lineCount = (): number => editorView.value?.state.doc.lines ?? 0

// Create underline decoration based on errors
const addUnderline = StateEffect.define<ErrorRange>({
    map: ({ from, to, severity, message, decoration }, change) =>
        validateRange({
            from: change.mapPos(from),
            to: change.mapPos(to),
            severity,
            message,
            decoration,
        }),
})

// Define a StateEffect for clearing all underlines
const clearUnderlines = StateEffect.define()

const underlineField = StateField.define<DecorationSet>({
    create() {
        return Decoration.none
    },
    update(underlines, tr) {
        underlines = underlines.map(tr.changes)
        for (let e of tr.effects) {
            // Handle the clearUnderlines effect by resetting underlines
            if (e.is(clearUnderlines)) {
                underlines = Decoration.none
            } else if (e.is(addUnderline)) {
                const decoration =
                    e.value.decoration || underlineMarkError(e.value.severity, e.value.message)
                underlines = underlines.update({
                    add: [decoration.range(e.value.from, e.value.to)],
                })
            }
        }
        return underlines
    },
    provide: (f) => EditorView.decorations.from(f),
})

const underlineMarkError = (severity: ErrorSeverity, msg: string) =>
    Decoration.mark({
        class: severity === ErrorSeverity.Warning ? 'yellow-wave' : 'red-wave',
        attributes: {},
    })

function clamp(n: number) {
    return Math.max(0, Math.min(n, editorView.value!.state.doc.length - 1))
}

function validateRange(range: ErrorRange): ErrorRange {
    range.from = clamp(range.from)
    range.to = clamp(range.to)
    if (range.from === range.to) {
        range.to = clamp(range.to + 1)
    }
    if (range.from === range.to) {
        range.from = clamp(range.from - 1)
    }
    if (range.from > range.to) {
        return {
            from: range.to,
            to: range.from,
            severity: range.severity,
            message: range.message,
            decoration: range.decoration,
        }
    }
    return range
}

const errorRanges = computed(() => {
    return errors.value
        .map((e) => {
            if (firstLine.value === 0) {
                return validateRange({
                    from: editorView.value!.state.doc.length - 2,
                    to: editorView.value!.state.doc.length - 1,
                    severity: e.severity,
                    message: e.message,
                })
            }
            const sLine = e.start.line - firstLine.value + 1
            const startLine = editorView.value!.state.doc.line(sLine)
            if (startLine) {
                const from = startLine.from + e.start.column
                const eLine = e.end.line - firstLine.value + 1
                if (eLine >= sLine && eLine <= lineCount()) {
                    const endLine = editorView.value!.state.doc.line(eLine)
                    if (endLine) {
                        return validateRange({
                            from: from,
                            to: endLine.from + e.end.column,
                            severity: e.severity,
                            message: e.message,
                        })
                    }
                } else {
                    return validateRange({
                        from: from,
                        to: from + 1,
                        severity: e.severity,
                        message: e.message,
                    })
                }
            }
            return undefined
        })
        .filter((e) => e !== undefined)
})

function underlineErrors() {
    let effects: StateEffect<unknown>[] = [
        clearUnderlines.of(null),
        ...errorRanges.value.map((e) => addUnderline.of(e)),
    ]

    editorView.value!.dispatch({ effects })
    return true
}

// Custom gutter marker for error symbols
const errorTipApps = new WeakMap<Node, ReturnType<typeof createApp>>()
class ErrorMarker extends GutterMarker {
    constructor(
        private severity: ErrorSeverity,
        private errors: ICompilerErrorDescription[]
    ) {
        super()
    }

    toDOM() {
        const marker = document.createElement('span')
        const app = createApp(ErrorTip, {
            errors: this.errors,
            severity: this.severity,
        })
        app.mount(marker)
        errorTipApps.set(marker, app)
        return marker
    }

    destroy(dom: Node) {
        errorTipApps.get(dom)?.unmount()
        errorTipApps.delete(dom)
    }
}

// Custom gutter for errors
const errorGutter = gutter({
    class: 'error-gutter',
    markers: (view: EditorView) => {
        let builder = new RangeSetBuilder<GutterMarker>()
        const errorsByLine = new Map<number, ICompilerErrorDescription[]>()

        errors.value.forEach((e) => {
            const lineNumber = e.start.line - firstLine.value + 1
            if (lineNumber >= 1 && lineNumber <= view.state.doc.lines) {
                if (!errorsByLine.has(lineNumber)) {
                    errorsByLine.set(lineNumber, [])
                }
                errorsByLine.get(lineNumber)!.push(e)
            }
        })

        const sortedLines = Array.from(errorsByLine.keys()).sort((a, b) => a - b)
        for (const lineNr of sortedLines) {
            const lineErrors = errorsByLine.get(lineNr)!
            const line = view.state.doc.line(lineNr)
            const maxSeverity = lineErrors.some((e) => e.severity === ErrorSeverity.Error)
                ? ErrorSeverity.Error
                : ErrorSeverity.Warning
            builder.add(line.from, line.from, new ErrorMarker(maxSeverity, lineErrors))
        }

        return builder.finish()
    },
})

watch(
    errors,
    () => {
        if (editorView.value === null) {
            return
        }
        console.log('Errors', errors.value)
        underlineErrors()
    },
    { immediate: true, deep: true }
)

watch(
    tagSet,
    () => {
        if (!editorView.value) {
            return
        }
        markTags(editorView.value, tagSet)
    },
    { deep: true }
)

defineExpose({
    view: editorView,
    lineCount,
    lineNr,
})
</script>
<style lang="sass">
.code-editor
    .system-code-box
        border: 1px dashed theme('colors.slate.300')

    .system-code-box-dark
